import sys
from math import sqrt

def num_divisors(n):
    count = 0
    for i in range(1, int(sqrt(n)) + 1):
        if n % i == 0:
            if n / i == i:
                count += 1
            else:
                count += 2
    return count

input = sys.stdin.read
data = input().split()
a, b, c = map(int, data)

result = 0
for i in range(1, a + 1):
    for j in range(1, b + 1):
        for k in range(1, c + 1):
            result += num_divisors(i * j * k)

print(result % 1073741824)

